def calculate_a(N):
    a = {}
    a[1] = 1
    a[2] = 1
    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        idx1 = a[n-1]
        idx2 = n - a[n-1]

        # We assume indices are always positive integers as per the problem constraints
        if idx1 in a and idx2 in a:
            a[n] = a[idx1] + a[idx2]
        else:
            # This should not happen if the sequence is well-defined for these small N
            a[n] = float('nan') 
    return a

N_max = 16
sequence = calculate_a(N_max)

print("n | a_n")
for n in range(1, N_max + 1):
    print(f"{n} | {sequence[n]}")

